    rows=row("DELUXE ROOM","10","—","4,800","—","—","—")+row("SUPER DELUXE ROOM","8","—","5,600","7,100","8,600","12,500")+row("SUITE ROOM","4","—","7,200","—","—","—")
    s3=sec(3,"Room categories & rates","Type each category once, then fill the plans this hotel offers — leave a plan empty if not offered",
      f'<div class=lbl style="margin-bottom:10px">Plan types shown in the table (tick / untick)</div><div style="display:flex;gap:10px;flex-wrap:wrap">{plans}</div>{newplan}<table><tr><th>CATEGORY</th><th style="text-align:right">TOTAL ROOMS</th>{TH("EP")}{TH("CP")}{TH("MAP")}{TH("AP")}{TH("SP1 · Honeymoon","#7b1fa2")}<th></th></tr>{rows}</table><div style="margin-top:12px"><span class="btn ghost" style="padding:8px 18px">+ Add room category</span> <span class=mini style="margin-left:10px">or pick from your list: Deluxe Room · Premium Room · Family Room · Suite Room …</span></div>',"")
    ai=lambda a,r:f'{ein(a)}{ein(r,"100%","right")}<span class="tag t-n">🗑</span>'
    s4=sec(4,"Add-ons / extra rates","Flower bed, candle light dinner, cake, extra mattress, meals …",f'<div style="margin-bottom:12px">{seg(["ADD ON BENEFITS","EXTRA RATE"],0)}</div><div style="display:grid;grid-template-columns:1fr 160px 40px;gap:10px;align-items:center">{ai("Extra mattress per person","₹ 1,500")}{ai("Flower bed decoration","₹ 3,000")}{ai("Candle light dinner","₹ 4,500")}</div><div style="margin-top:12px"><span class="btn ghost" style="padding:8px 18px">+ Add item</span> <span class=mini style="margin-left:10px">or choose from your add-on list ▾ (managed in Settings)</span></div>')
    fac=[("Swimming pool",True,"Goes to the Pool list"),("Sea view",True,"Goes to the Sea view list"),("Beach front",False,""),("Restaurant",True,""),("Bar / wine",False,""),("Wi-Fi",True,""),("Free parking",True,""),("Spa / massage",False,""),("Gym",False,""),("Lift",False,""),("Bathtub rooms",False,""),("Private balcony",False,""),("Kids play area",False,""),("Pet friendly",False,""),(f"{'Jetty' if isl!='Port Blair' else 'Airport'} pickup",True,""),("Candle light dinner area",False,"")]
    s5=sec(5,"Facilities","Tick every facility this hotel has — the hotel is added to the matching lists",'<div style="display:grid;grid-template-columns:repeat(4,1fr);gap:10px">'+"".join(cbx(a,b,c) for a,b,c in fac)+'</div><div style="margin-top:14px"><span class="btn ghost" style="padding:8px 18px">+ Add a new facility</span> <span class=mini style="margin-left:10px">Facility list is managed in Settings → Facilities</span></div>')
    chips=lambda items:"".join(f'<span class="tag t-b" style="margin:3px 4px 3px 0">{x}</span>' for x in items)
    s6=sec(6,"Submit to categories","Check where this hotel will appear, then press Submit",f'<div style="display:grid;grid-template-columns:150px 1fr;row-gap:12px;font-size:14px;align-items:center"><b>Island</b><div>{chips([isl])}</div><b>Class</b><div>{chips(["Mid"])}</div><b>Star list</b><div>{chips(["4 STAR"])}</div><b>Price range</b><div>{chips(["₹4,100 – ₹5,000","₹5,100 – ₹20,000"])}</div><b>Facility lists</b><div>{chips(["Pool","Sea view","Restaurant","Wi-Fi","Free parking","Pickup"])}</div><b>Also updated</b><div>{chips(["Hotel dropdown","All Hotels page","Dashboard counts","Low-price ranking"])}</div></div><div style="display:flex;gap:12px;margin-top:22px"><span class="btn" style="padding:14px 34px;font-size:15px">✅ Submit &amp; Update All Hotels</span><span class="btn ghost" style="padding:14px 28px">💾 Save as draft</span><span class="btn red" style="padding:14px 28px">Clear form</span></div>')
    done=lambda t,ok=True,opt=False:f'<div style="display:flex;gap:10px;padding:8px 0;align-items:center;font-size:14px"><span class=badge style="width:22px;height:22px;font-size:12px;background:{"#34a853" if ok else "#dadce0"}">{"✓" if ok else ""}</span><span style="flex:1;{"" if ok else "color:#80868b"}">{t}</span>{"<span class=mini>optional</span>" if opt else ""}</div>'
